#!/usr/bin/env bash
# steps/05-bootstrap-status-and-tls-backends/solution/solve.sh
#
# GENERATED by misc/onion-routing-client-multiversion/build-oracle.sh.
#
# Installs the Oracle for step 05 — upstream arti at arti-v0.0.4 — into
# /app. Harbor runs this INSTEAD of the agent when the task is exercised as an
# Oracle ladder, so what lands in /app here is what this step's verifier grades.
#
# It applies a payload that was produced offline and checksummed; it never
# fetches anything, and it never edits the tests.
set -euo pipefail

# Defaults to /app, which is what Harbor provides. The override exists so the
# twelve-step chain can be rehearsed offline on the authoring host, where
# there is no /app and no root: it changes where the payload is installed,
# never what is checked afterwards.
APP="${ORACLE_APP_ROOT:-/app}"
PAYLOAD="$(cd "$(dirname "$0")" && pwd)/payload"

say() { printf '[solve 05] %s\n' "$*"; }

# ---------------------------------------------------------------------------
# 1. The payload is what it was when the step was reviewed
# ---------------------------------------------------------------------------
say "verifying payload"
( cd "$PAYLOAD" && sha256sum --quiet -c SHA256SUMS )

# ---------------------------------------------------------------------------
# 2. Record what the task itself seeded, so step 3 can prove it survived
# ---------------------------------------------------------------------------
# /app is not empty when this runs: it carries this step's workdir material
# (TEST_INTERFACE.md, SPEC_NOTES.md, the reading guide) and, from step 02 on,
# the previous step's installed Oracle. The payload must add to that, not
# replace it — a solution that wipes /app would pass its own step and destroy
# the agent-visible material every later step depends on.
SEEDED=$(find "$APP" -maxdepth 2 -name 'TEST_INTERFACE.md' -o -maxdepth 2 -name 'SPEC_NOTES.md' 2>/dev/null | sort)

# ---------------------------------------------------------------------------
# 3. Install
# ---------------------------------------------------------------------------
say "applying arti-v0.0.3 -> arti-v0.0.4"
git -C "$APP" apply --binary --whitespace=nowarn -p2 "$PAYLOAD/arti-v0.0.3-to-arti-v0.0.4.patch"

# ---------------------------------------------------------------------------
# 4. The installed tree is byte-for-byte the upstream checkpoint
# ---------------------------------------------------------------------------
# MANIFEST.sha256 lists every file in upstream arti at arti-v0.0.4, by path
# relative to /app. Checking it is what makes this an Oracle rather than an
# approximation: a patch that applied with fuzz, a tar that half-extracted, or
# a stale file left behind by the previous step all show up here.
say "verifying installed tree against arti-v0.0.4"
( cd "$APP" && sha256sum --quiet -c "$PAYLOAD/MANIFEST.sha256" )
say "installed tree matches arti-v0.0.4 exactly"

# ---------------------------------------------------------------------------
# 5. The task's own seeded material survived
# ---------------------------------------------------------------------------
missing=0
while IFS= read -r f; do
    [ -z "$f" ] && continue
    if [ ! -f "$f" ]; then
        printf '[solve 05] ERROR: install removed seeded file %s\n' "$f" >&2
        missing=1
    fi
done <<< "$SEEDED"
[ "$missing" -eq 0 ] || exit 1

say "done"
